const fs = require('fs');
const path = require('path');
const { withDangerousMod } = require('expo/config-plugins');

/**
 * Raises the deployment target of every CocoaPods target to at least the app's.
 *
 * Xcode 27 rejects targets below iOS 15 ("The iOS Simulator deployment target
 * 'IPHONEOS_DEPLOYMENT_TARGET' is set to 9.0, but the range of supported
 * deployment target versions is 15.0 to 27.x"). Some pods (SDWebImage, Mute,
 * RNSVGFilters) still declare 9.0 / 12.4, and the Podfile is regenerated by
 * prebuild, so the fix is applied here.
 */

const MARKER = '# @generated withPodsDeploymentTarget';

const POST_INSTALL_HOOK = `
    ${MARKER}
    min_ios = podfile_properties['ios.deploymentTarget'] || '17.0'
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |build_config|
        current = build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        if current.nil? || Gem::Version.new(current) < Gem::Version.new(min_ios)
          build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = min_ios
        end
      end
    end
`;

const ANCHOR = /(react_native_post_install\([\s\S]*?\n\s*\)\n)/;

function withPodsDeploymentTarget(config) {
  return withDangerousMod(config, [
    'ios',
    (config) => {
      const podfilePath = path.join(config.modRequest.platformProjectRoot, 'Podfile');
      const contents = fs.readFileSync(podfilePath, 'utf8');
      if (contents.includes(MARKER)) {
        return config;
      }
      if (!ANCHOR.test(contents)) {
        throw new Error(
          'withPodsDeploymentTarget: could not find react_native_post_install(...) in ios/Podfile. ' +
            'The Expo template changed; update plugins/withPodsDeploymentTarget.js.',
        );
      }
      fs.writeFileSync(podfilePath, contents.replace(ANCHOR, `$1${POST_INSTALL_HOOK}`));
      return config;
    },
  ]);
}

module.exports = withPodsDeploymentTarget;
